class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  List<NewsModel> _newsList = const [];

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCachedThenNetwork();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  /// Cache-then-network: мгновенно показываем кэш, параллельно обновляем из сети.
  Future<void> _loadCachedThenNetwork() async {
    final newsRepository = context.read<NewsRepository>();

    // 1. Мгновенно загружаем кэш (БД).
    final List<NewsModel> cached = await newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: false));

    if (!mounted) return;

    setState(() {
      _newsList = cached;
      // Анимация появляется только при первой загрузке.
      _scaleController.forward();
    });

    // 2. Параллельно запрашиваем свежие данные из сети и обновляем кэш.
    try {
      final List<NewsModel> fresh = await newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
      if (mounted) {
        setState(() => _newsList = fresh);
      }
    } catch (_) {
      // Если сеть недоступна — показываем то, что есть в кэше.
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ScaleTransition(
        scale: _scaleAnimation,
        child: ListView.builder(
          itemCount: _newsList.length,
          itemBuilder: (BuildContext context, int index) {
            final NewsModel news = _newsList[index];

            return Padding(
              key: ValueKey(news.link),
              padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
              child: NewsCard(model: news),
            );
          },
          padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
        ),
      ),
    );
  }
}
